    '<tab>;', '<return>;', '<null>;', '<backspace>;', '<boundary>;', 'not <space>;',
    'not <digit>;', 'not <word>;', 'not <boundary>;', 'a to z;', 'm to q;', 'not abc;', 'not a to z;'
]
quant_targets = atoms + [
    'match { \"a\"; \"b\"; }',
    'either { \"a\"; \"bc\"; }',
    'capture { \"a\"; }',
    'capture foo { \"a\"; }',
    'ahead { \"a\"; }',
    'behind { "'`[a-z]+`; }'"',
]

def group(depth):
    if depth <= 0:
        return random.choice(atoms)
    kind = random.choice(['match', 'either', 'capture', 'capture_name', 'ahead', 'behind', 'not_ahead', 'not_behind', 'quant', 'concat'])
    if kind == 'match':
        return 'match { ' + ' '.join(expr(depth-1) for _ in range(random.randint(1,3))) + ' }'
    if kind == 'either':
        return 'either { ' + ' '.join(expr(depth-1) for _ in range(random.randint(1,3))) + ' }'
    if kind == 'capture':
        return 'capture { ' + ' '.join(expr(depth-1) for _ in range(random.randint(1,3))) + ' }'
    if kind == 'capture_name':
        name = random.choice(['foo', 'bar', 'Foo', 'foo bar'])
        return f'capture {name} {{ ' + ' '.join(expr(depth-1) for _ in range(random.randint(1,2))) + ' }'
    if kind == 'ahead':
        return 'ahead { ' + ' '.join(expr(depth-1) for _ in range(random.randint(1,2))) + ' }'
    if kind == 'behind':
        return 'behind { ' + ' '.join(expr(depth-1) for _ in range(random.randint(1,2))) + ' }'
    if kind == 'not_ahead':
        return 'not ahead { ' + ' '.join(expr(depth-1) for _ in range(random.randint(1,2))) + ' }'
    if kind == 'not_behind':
        return 'not behind { ' + ' '.join(expr(depth-1) for _ in range(random.randint(1,2))) + ' }'
    if kind == 'quant':
        target = random.choice(quant_targets + [group(depth-1)])
        qkind = random.choice(['some', 'any', 'option', 'exact', 'range', 'lazy_some', 'lazy_any', 'lazy_option', 'lazy_exact', 'lazy_range', 'over', 'lazy_over'])
        if qkind == 'some':
            return f'some of {target}'
        if qkind == 'any':
            return f'any of {target}'
        if qkind == 'option':
            return f'option of {target}'
        if qkind == 'exact':
            return f'{random.randint(0,3)} of {target}'
        if qkind == 'range':
            a = random.randint(0,2); b = random.randint(max(a,2),4); return f'{a} to {b} of {target}'
        if qkind == 'lazy_some':
            return f'lazy some of {target}'
        if qkind == 'lazy_any':
            return f'lazy any of {target}'
        if qkind == 'lazy_option':
            return f'lazy option of {target}'
        if qkind == 'lazy_exact':
            return f'lazy {random.randint(0,3)} of {target}'
        if qkind == 'lazy_range':
            a = random.randint(0,2); b = random.randint(max(a,2),4); return f'lazy {a} to {b} of {target}'
        if qkind == 'over':
            return f'over {random.randint(0,3)} of {target}'
        return f'lazy over {random.randint(0,3)} of {target}'
    return ' '.join(expr(depth-1) for _ in range(random.randint(1,3)))

def expr(depth):
    return group(depth)


def run_orig(args, input_text=None):
    cmd = 'exec -a executable ' + ' '.join(shlex.quote(x) for x in ['./executable.original', *args])
    return subprocess.run(['bash', '-lc', cmd], cwd='/workspace', input=input_text, text=True, capture_output=True)

def run_ours(args, input_text=None):
    return subprocess.run(['./executable', *args], cwd='/workspace', input=input_text, text=True, capture_output=True)

samples = ['','a','ab','abc','aaaa','b','bc','x','#hello',' hello','\\n','\\t','aaab','z','m','q']
